using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ENC.OpcionesPregunta;namespace GraphApi.Services.ENC.OpcionesPregunta{    public class OpcionesPreguntaService : IOpcionesPreguntaService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public OpcionesPreguntaService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadOpcionesPregunta>> GetOpcionesPreguntas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM enc.OpcionesPregunta (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadOpcionesPregunta>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetOpcionesPreguntasDynamic(            int? opcionPreguntaID,            int? preguntaID,            string? texto,            string? valor,            int? orden,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "OpcionPreguntaID, PreguntaID, Texto, Valor, Orden, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM enc.OpcionesPregunta (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (opcionPreguntaID.HasValue)            {                vSql.Append(" AND OpcionPreguntaID = @OpcionPreguntaID");                vParameters.Add("OpcionPreguntaID",opcionPreguntaID);            }            if (!string.IsNullOrWhiteSpace(texto))            {                vSql.Append(" AND Texto LIKE @Texto");                vParameters.Add("Texto",$"%{texto}%");            }            if (!string.IsNullOrWhiteSpace(valor))            {                vSql.Append(" AND Valor LIKE @Valor");                vParameters.Add("Valor",$"%{valor}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadOpcionesPregunta> CreateOpcionesPregunta(clCreateOpcionesPregunta objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO enc.OpcionesPregunta                (PreguntaID, Texto, Valor, Orden, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@PreguntaID, @Texto, @Valor, @Orden, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.PreguntaID,                objInput.Texto,                objInput.Valor,                objInput.Orden,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT OpcionPreguntaID, PreguntaID, Texto, Valor, Orden, bEliminado                FROM enc.OpcionesPregunta (NOLOCK)                WHERE OpcionPreguntaID = @OpcionPreguntaID;";            var vReadParams = new { OpcionPreguntaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadOpcionesPregunta>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el OpcionesPregunta con ID {vNewId}.");            return vCreated;        }        public async Task<clReadOpcionesPregunta?> UpdateOpcionesPregunta(clUpdateOpcionesPregunta objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("OpcionPreguntaID", objInput.OpcionPreguntaID);            if (objInput.PreguntaID != null)            {                vSets.Add("PreguntaID = @PreguntaID");                vParameters.Add("PreguntaID", objInput.PreguntaID);            }            if (objInput.Texto is not null)            {                vSets.Add("Texto = @Texto");                vParameters.Add("Texto", objInput.Texto);            }            if (objInput.Valor is not null)            {                vSets.Add("Valor = @Valor");                vParameters.Add("Valor", objInput.Valor);            }            if (objInput.Orden != null)            {                vSets.Add("Orden = @Orden");                vParameters.Add("Orden", objInput.Orden);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE enc.OpcionesPregunta                SET {vSetClause}                WHERE OpcionPreguntaID = @OpcionPreguntaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT OpcionPreguntaID, PreguntaID, Texto, Valor, Orden, bEliminado                FROM enc.OpcionesPregunta (NOLOCK)                WHERE OpcionPreguntaID = @OpcionPreguntaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadOpcionesPregunta>(sSelect, new {  objInput.OpcionPreguntaID });        }        public async Task<bool> DeleteOpcionesPregunta(int nOpcionesPreguntaID)        {            const string sSql = @"                DELETE FROM enc.OpcionesPregunta                WHERE OpcionPreguntaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nOpcionesPreguntaID });            return vAffected > 0;        }    }}